const STEREOTYPE_ID = "472c2df3-e807-4cf6-89b1-8213cd485c26";
const META_KEY = "blazor-auth-page-id";
const NEWLY_CREATED_META_KEY = "blazor-auth-page-newly-created";
const PAGE_STEREOTYPE = "Page";
const NAVIGATION_ASSOCIATION = "Navigation";

function page(id, name, route, title) { return { id: id, name: name, route: route, title: title }; }
function shared(id, name) { return { id: id, name: name }; }

// Login/Register/ForgotPassword/ResetPassword/ConfirmEmail/ResendEmailConfirmation exist under more than
// one Authentication mode, but their generated content genuinely differs per mode (e.g. the
// AuthPageDefaultContentFactoryExtension content builders branch on the active Authentication mode today;
// that branching will move to fully separate content per id in the future — do not collapse these ids
// back down in the meantime). Prefixing each mode's copy keeps its Component/page id — and therefore its
// generated file — distinct, so switching Authentication modes creates/removes the right components
// instead of one mode's page silently reusing another mode's already-generated file.
const SECURITY_TYPE_PREFIX = {
    "ASP.NET Core Identity": "identity",
    "JWT": "jwt",
    "OIDC": "oidc",
    "None": null
};
const SHARED_PAGE_IDS = ["login", "register", "forgot-password", "reset-password", "confirm-email", "resend-email-confirmation"];
// Bootstrap-only UX primitives with no MudBlazor-folder equivalent and no code-behind — MudBlazor's own
// components (MudPaper/MudIcon/MudTextField, etc.) are used directly instead, so these should never be
// modelled (and therefore never generated) when MudBlazor is installed.
const HIDE_IF_MUDBLAZOR_IDS = ["account-hero", "ux-field", "ux-icon"];

function authPageId(prefix, baseId) { return prefix + "-" + baseId; }

const IDENTITY_PAGES = [
    page(authPageId("identity", "login"), "Login", "/Account/Login", "Login"),
    page(authPageId("identity", "register"), "Register", "/Account/Register", "Register"),
    page(authPageId("identity", "forgot-password"), "ForgotPassword", "/Account/ForgotPassword", "Forgot Password"),
    page(authPageId("identity", "reset-password"), "ResetPassword", "/Account/ResetPassword", "Reset Password"),
    page(authPageId("identity", "confirm-email"), "ConfirmEmail", "/Account/ConfirmEmail", "Confirm Email"),
    page(authPageId("identity", "resend-email-confirmation"), "ResendEmailConfirmation", "/Account/ResendEmailConfirmation", "Resend Email Confirmation"),
    page("access-denied", "AccessDenied", "/Account/AccessDenied", "Access Denied"),
    page("confirm-email-change", "ConfirmEmailChange", "/Account/ConfirmEmailChange", "Confirm Email Change"),
    page("external-login", "ExternalLogin", "/Account/ExternalLogin", "External Login"),
    page("forgot-password-confirmation", "ForgotPasswordConfirmation", "/Account/ForgotPasswordConfirmation", "Forgot Password Confirmation"),
    page("invalid-password-reset", "InvalidPasswordReset", "/Account/InvalidPasswordReset", "Invalid Password Reset"),
    page("invalid-user", "InvalidUser", "/Account/InvalidUser", "Invalid User"),
    page("lockout", "Lockout", "/Account/Lockout", "Lockout"),
    page("login-with-2fa", "LoginWith2fa", "/Account/LoginWith2fa", "Login With 2FA"),
    page("login-with-recovery-code", "LoginWithRecoveryCode", "/Account/LoginWithRecoveryCode", "Login With Recovery Code"),
    page("register-confirmation", "RegisterConfirmation", "/Account/RegisterConfirmation", "Register Confirmation"),
    page("reset-password-confirmation", "ResetPasswordConfirmation", "/Account/ResetPasswordConfirmation", "Reset Password Confirmation")
];

const IDENTITY_MANAGE_PAGES = [
    page("manage", "Index", "/Account/Manage", "Manage"),
    page("manage-email", "Email", "/Account/Manage/Email", "Manage Email"),
    page("manage-change-password", "ChangePassword", "/Account/Manage/ChangePassword", "Change Password"),
    page("manage-set-password", "SetPassword", "/Account/Manage/SetPassword", "Set Password"),
    page("manage-two-factor-authentication", "TwoFactorAuthentication", "/Account/Manage/TwoFactorAuthentication", "Two Factor Authentication"),
    page("manage-disable-2fa", "Disable2fa", "/Account/Manage/Disable2fa", "Disable 2FA"),
    page("manage-enable-authenticator", "EnableAuthenticator", "/Account/Manage/EnableAuthenticator", "Enable Authenticator"),
    page("manage-reset-authenticator", "ResetAuthenticator", "/Account/Manage/ResetAuthenticator", "Reset Authenticator"),
    page("manage-generate-recovery-codes", "GenerateRecoveryCodes", "/Account/Manage/GenerateRecoveryCodes", "Generate Recovery Codes"),
    page("manage-personal-data", "PersonalData", "/Account/Manage/PersonalData", "Personal Data"),
    page("manage-delete-personal-data", "DeletePersonalData", "/Account/Manage/DeletePersonalData", "Delete Personal Data"),
    page("manage-external-logins", "ExternalLogins", "/Account/Manage/ExternalLogins", "External Logins")
];

const IDENTITY_SHARED = [
    //shared("account-layout", "AccountLayout"),
    shared("account-hero", "AccountHero"),
    shared("app-user-menu", "AppUserMenu"),
    shared("external-login-picker", "ExternalLoginPicker"),
    //shared("manage-layout", "ManageLayout"),
    shared("manage-nav-menu", "ManageNavMenu"),
    shared("show-recovery-codes", "ShowRecoveryCodes"),
    shared("status-message", "StatusMessage"),
    shared("ux-field", "UxField"),
    shared("ux-icon", "UxIcon")
];

const JWT_PAGES = [
    page(authPageId("jwt", "login"), "Login", "/Account/Login", "Login"),
    page(authPageId("jwt", "register"), "Register", "/Account/Register", "Register"),
    page(authPageId("jwt", "forgot-password"), "ForgotPassword", "/Account/ForgotPassword", "Forgot Password"),
    page(authPageId("jwt", "reset-password"), "ResetPassword", "/Account/ResetPassword", "Reset Password"),
    page(authPageId("jwt", "confirm-email"), "ConfirmEmail", "/Account/ConfirmEmail", "Confirm Email"),
    page(authPageId("jwt", "resend-email-confirmation"), "ResendEmailConfirmation", "/Account/ResendEmailConfirmation", "Resend Email Confirmation")
];
const JWT_SHARED = [
    //shared("account-layout", "AccountLayout"),
    shared("account-hero", "AccountHero"),
    shared("status-message", "StatusMessage"),
    shared("ux-field", "UxField"),
    shared("ux-icon", "UxIcon")
];

const OIDC_PAGES = [
    page(authPageId("oidc", "login"), "Login", "/Account/Login", "Login")
];
const OIDC_SHARED = [
    //shared("account-layout", "AccountLayout")
];

const PAGE_DEFINITIONS = {
    "ASP.NET Core Identity": { pages: IDENTITY_PAGES, managePages: IDENTITY_MANAGE_PAGES, shared: IDENTITY_SHARED },
    "JWT": { pages: JWT_PAGES, managePages: [], shared: JWT_SHARED },
    "OIDC": { pages: OIDC_PAGES, managePages: [], shared: OIDC_SHARED },
    "None": { pages: [], managePages: [], shared: [] }
};

// Edges between the six ids that exist under more than one Authentication mode. Resolved per mode
// (via resolveNavigationId) into that mode's prefixed ids before being applied.
const SHARED_NAVIGATION_TEMPLATE = [
    ["login", "forgot-password"],
    ["login", "register"],
    ["login", "resend-email-confirmation"],
    ["register", "login"],
    ["forgot-password", "login"],
    ["reset-password", "login"],
    ["confirm-email", "login"],
    ["resend-email-confirmation", "login"]
];

// Edges only reachable under ASP.NET Core Identity (2FA, external login, Manage/*, etc.) — these also
// reference some of the six shared ids (e.g. "login"), so they are resolved with the Identity prefix too.
const IDENTITY_ONLY_NAVIGATION = [
    ["login", "login-with-2fa"],
    ["login", "lockout"],
    ["external-login-picker", "external-login"],
    ["register", "register-confirmation"],
    ["reset-password", "invalid-password-reset"],
    ["reset-password", "reset-password-confirmation"],
    ["external-login", "login"],
    ["external-login", "lockout"],
    ["external-login", "register-confirmation"],
    ["login-with-2fa", "login-with-recovery-code"],
    ["login-with-2fa", "lockout"],
    ["login-with-recovery-code", "lockout"],
    ["confirm-email-change", "login"],
    ["register-confirmation", "confirm-email"],
    ["reset-password-confirmation", "login"],
    ["manage-nav-menu", "manage"],
    ["manage-nav-menu", "manage-email"],
    ["manage-nav-menu", "manage-change-password"],
    ["manage-nav-menu", "manage-external-logins"],
    ["manage-nav-menu", "manage-two-factor-authentication"],
    ["manage-nav-menu", "manage-personal-data"],
    ["app-user-menu", "manage"],
    ["manage-change-password", "manage-set-password"],
    ["manage-set-password", "manage-change-password"],
    ["manage-personal-data", "manage-delete-personal-data"],
    ["manage-two-factor-authentication", "manage-generate-recovery-codes"],
    ["manage-two-factor-authentication", "manage-enable-authenticator"],
    ["manage-two-factor-authentication", "manage-disable-2fa"],
    ["manage-two-factor-authentication", "manage-reset-authenticator"],
    ["manage-disable-2fa", "manage-reset-authenticator"],
    ["manage-disable-2fa", "manage-two-factor-authentication"],
    ["manage-enable-authenticator", "manage-two-factor-authentication"],
    ["manage-reset-authenticator", "manage-enable-authenticator"],
    ["manage-generate-recovery-codes", "manage-reset-authenticator"]
];

function resolveNavigationId(prefix, id) {
    return SHARED_PAGE_IDS.indexOf(id) !== -1 ? authPageId(prefix, id) : id;
}

function getNavigationDefinitions(securityType) {
    const prefix = SECURITY_TYPE_PREFIX[securityType];
    if (!prefix) {
        return [];
    }
    const edges = SHARED_NAVIGATION_TEMPLATE.map(function (edge) {
        return [resolveNavigationId(prefix, edge[0]), resolveNavigationId(prefix, edge[1])];
    });
    if (securityType === "ASP.NET Core Identity") {
        IDENTITY_ONLY_NAVIGATION.forEach(function (edge) {
            edges.push([resolveNavigationId(prefix, edge[0]), resolveNavigationId(prefix, edge[1])]);
        });
    }
    return edges;
}

function findChildFolder(parent, name) {
    const match = parent.getChildren("Folder").find(function (f) { return f.getName() === name; });
    return match ? match : null;
}

function ensureChildFolder(parent, name) {
    const existing = findChildFolder(parent, name);
    return existing ? existing : parent.addChild("Folder", name);
}

function addNavigation(source, target) {
    const handle = source.getAssociations(NAVIGATION_ASSOCIATION).find(function (assoc) {
        const other = assoc.getAssociatedElement();
        return other && other.id === target.id;
    });
    if (handle) {
        if (!handle.isSourceEnd()) {
            handle.setBidirectional(true);
        }
        return handle;
    }
    return createAssociation(NAVIGATION_ASSOCIATION, source.id, target.id);
}

function syncNavigations(navigationDefinitions) {
    const byId = {};
    findElements({ specialization: "Component" })
        .filter(function (c) { return c.hasMetadata(META_KEY); })
        .forEach(function (c) { byId[c.getMetadata(META_KEY)] = c; });

    navigationDefinitions.forEach(function (edge) {
        const source = byId[edge[0]];
        const target = byId[edge[1]];
        if (source && target) {
            addNavigation(source, target);
        }
    });
}

async function runSync(securityType) {
    const definition = PAGE_DEFINITIONS[securityType];
    // MudBlazor ships its own Hero-equivalent markup (MudPaper/MudIcon used directly in Login etc.),
    // so account-hero should never be modelled (and therefore never generated) when MudBlazor is installed.
    const mudBlazorInstalled = application.isModuleInstalled("Intent.Blazor.Components.MudBlazor");
    const sharedTargets = definition.shared.filter(function (s) {
        return !(HIDE_IF_MUDBLAZOR_IDS.indexOf(s.id) !== -1 && mudBlazorInstalled);
    });
    const allTargets = definition.pages.concat(definition.managePages, sharedTargets);
    const targetIds = {};
    allTargets.forEach(function (t) { targetIds[t.id] = true; });

    const managed = findElements({ specialization: "Component" }).filter(function (c) { return c.hasMetadata(META_KEY); });
    const toRemove = managed.filter(function (c) { return !targetIds[c.getMetadata(META_KEY)]; });

    let accountFolder = null;
    if (managed.length > 0) {
        let cur = managed[0].getParent();
        while (cur && cur.getName() !== "Account") {
            cur = cur.getParent();
        }
        accountFolder = cur;
    }

    if (!accountFolder && allTargets.length > 0) {
        const homePage = findElements({ specialization: "Component" }).find(function (c) {
            if (!c.hasStereotype(PAGE_STEREOTYPE)) {
                return false;
            }
            const route = c.getStereotype(PAGE_STEREOTYPE).getProperty("Route").getValue();
            return route === "/" || route === "" || c.getName() === "Home" || c.getName() === "HomePage";
        });
        const pagesRootFolder = homePage ? homePage.getParent() : null;
        let ancestor = pagesRootFolder;
        while (ancestor && ancestor.getName() !== "Pages") {
            ancestor = ancestor.getParent();
        }
        const parent = ancestor ? (ancestor.getParent() || ancestor.getPackage()) : (pagesRootFolder || element.getPackage());
        const existingAccountFolder = findChildFolder(parent, "Account");
        accountFolder = existingAccountFolder ? existingAccountFolder : parent.addChild("Folder", "Account");
        const accountDiagram = accountFolder.getChildren("Diagram").find(function (d) { return d.getName() === "Account"; });
        if (!accountDiagram) {
            accountFolder.addChild("Diagram", "Account");
        }
    }

    toRemove.forEach(function (c) { c.delete(); });

    const createdIds = [];
    let pagesFolder = null;
    let manageFolder = null;
    let sharedFolder = null;

    if (accountFolder) {
        pagesFolder = ensureChildFolder(accountFolder, "Pages");
        manageFolder = ensureChildFolder(pagesFolder, "Manage");
        sharedFolder = ensureChildFolder(accountFolder, "Shared");

        function syncPage(def, folder) {
            let comp = managed.find(function (c) { return c.getMetadata(META_KEY) === def.id; });
            if (!comp) {
                comp = folder.addChild("Component", def.name);
                createdIds.push(comp.id);
                comp.setMetadata(NEWLY_CREATED_META_KEY, "true");
            }
            const st = comp.ensureStereotype(PAGE_STEREOTYPE);
            st.setProperty("Route", def.route);
            st.setProperty("Title", def.title);
            comp.setMetadata(META_KEY, def.id);
        }

        function syncShared(def, folder) {
            let comp = managed.find(function (c) { return c.getMetadata(META_KEY) === def.id; });
            if (!comp) {
                comp = folder.addChild("Component", def.name);
                createdIds.push(comp.id);
                comp.setMetadata(NEWLY_CREATED_META_KEY, "true");
            }
            comp.setMetadata(META_KEY, def.id);
        }

        definition.pages.forEach(function (p) { syncPage(p, pagesFolder); });
        definition.managePages.forEach(function (p) { syncPage(p, manageFolder); });
        sharedTargets.forEach(function (s) { syncShared(s, sharedFolder); });
    }

    element.setMetadata("authentication", securityType);

    if (accountFolder) {
        try {
            syncNavigations(getNavigationDefinitions(securityType));

            if (createdIds.length > 0) {
                const diagramElement = accountFolder.getChildren("Diagram").find(function (d) { return d.getName() === "Account"; });
                if (diagramElement) {
                    const diagram = await diagramElement.openDiagram();
                    const position = diagram.mousePosition || { x: 0, y: 0 };
                    diagram.layoutVisuals(createdIds, position, true);
                }
            }

            if (manageFolder.getChildren().length === 0) {
                manageFolder.delete();
            }
            if (pagesFolder.getChildren().length === 0) {
                pagesFolder.delete();
            }
            if (sharedFolder.getChildren().length === 0) {
                sharedFolder.delete();
            }
            const remaining = accountFolder.getChildren().filter(function (c) {
                return c !== pagesFolder && c !== sharedFolder && c.getSpecialization() !== "Diagram";
            });
            if (remaining.length === 0 && !pagesFolder.getParent() && !sharedFolder.getParent()) {
                accountFolder.getChildren("Diagram").forEach(function (d) { d.delete(); });
                accountFolder.delete();
            }
        } catch (e) {
            console.log("Navigation sync, diagram placement, or folder cleanup failed (non-fatal): " + e);
        }
    }
}

const stereotype = element.getStereotype(STEREOTYPE_ID);
const securityType = stereotype.getProperty("Authentication").getValue();
await runSync(securityType);

