    return SHARED_PAGE_IDS.indexOf(id) !== -1 ? authPageId(prefix, id) : id;
}

function getNavigationDefinitions(securityType) {
    const prefix = SECURITY_TYPE_PREFIX[securityType];
    if (!prefix) {
        return [];
    }
    const edges = SHARED_NAVIGATION_TEMPLATE.map(function (edge) {
        return [resolveNavigationId(prefix, edge[0]), resolveNavigationId(prefix, edge[1])];
    });
    if (securityType === "ASP.NET Core Identity") {
        IDENTITY_ONLY_NAVIGATION.forEach(function (edge) {
            edges.push([resolveNavigationId(prefix, edge[0]), resolveNavigationId(prefix, edge[1])]);
        });
    }
    return edges;
}

function findChildFolder(parent, name) {
    const match = parent.getChildren("Folder").find(function (f) { return f.getName() === name; });
    return match ? match : null;
}

function ensureChildFolder(parent, name) {
    const existing = findChildFolder(parent, name);
    return existing ? existing : parent.addChild("Folder", name);
}

function addNavigation(source, target) {
    const handle = source.getAssociations(NAVIGATION_ASSOCIATION).find(function (assoc) {
        const other = assoc.getAssociatedElement();
        return other && other.id === target.id;
    });
    if (handle) {
        if (!handle.isSourceEnd()) {
            handle.setBidirectional(true);
        }
        return handle;
    }
    return createAssociation(NAVIGATION_ASSOCIATION, source.id, target.id);
}

function syncNavigations(navigationDefinitions) {
    const byId = {};
    findElements({ specialization: "Component" })
        .filter(function (c) { return c.hasMetadata(META_KEY); })
        .forEach(function (c) { byId[c.getMetadata(META_KEY)] = c; });

    navigationDefinitions.forEach(function (edge) {
        const source = byId[edge[0]];
        const target = byId[edge[1]];
        if (source && target) {
            addNavigation(source, target);
        }
    });
}

async function runSync(securityType) {
    const definition = PAGE_DEFINITIONS[securityType];
    // MudBlazor ships its own Hero-equivalent markup (MudPaper/MudIcon used directly in Login etc.),
    // so account-hero should never be modelled (and therefore never generated) when MudBlazor is installed.
    const mudBlazorInstalled = application.isModuleInstalled("Intent.Blazor.Components.MudBlazor");
    const sharedTargets = definition.shared.filter(function (s) {
        return !(HIDE_IF_MUDBLAZOR_IDS.indexOf(s.id) !== -1 && mudBlazorInstalled);
    });
    const allTargets = definition.pages.concat(definition.managePages, sharedTargets);
    const targetIds = {};
    allTargets.forEach(function (t) { targetIds[t.id] = true; });

    const managed = findElements({ specialization: "Component" }).filter(function (c) { return c.hasMetadata(META_KEY); });
    const toRemove = managed.filter(function (c) { return !targetIds[c.getMetadata(META_KEY)]; });

    let accountFolder = null;
    if (managed.length > 0) {
        let cur = managed[0].getParent();
        while (cur && cur.getName() !== "Account") {
            cur = cur.getParent();
        }
        accountFolder = cur;
    }

    if (!accountFolder && allTargets.length > 0) {
        const homePage = findElements({ specialization: "Component" }).find(function (c) {
            if (!c.hasStereotype(PAGE_STEREOTYPE)) {
                return false;
            }
            const route = c.getStereotype(PAGE_STEREOTYPE).getProperty("Route").getValue();
            return route === "/" || route === "" || c.getName() === "Home" || c.getName() === "HomePage";
        });
        const pagesRootFolder = homePage ? homePage.getParent() : null;
        let ancestor = pagesRootFolder;
        while (ancestor && ancestor.getName() !== "Pages") {
            ancestor = ancestor.getParent();
        }
        const parent = ancestor ? (ancestor.getParent() || ancestor.getPackage()) : (pagesRootFolder || element.getPackage());
        const existingAccountFolder = findChildFolder(parent, "Account");
        accountFolder = existingAccountFolder ? existingAccountFolder : parent.addChild("Folder", "Account");
        const accountDiagram = accountFolder.getChildren("Diagram").find(function (d) { return d.getName() === "Account"; });
        if (!accountDiagram) {
            accountFolder.addChild("Diagram", "Account");
        }
    }

    toRemove.forEach(function (c) { c.delete(); });

    const createdIds = [];
    let pagesFolder = null;
    let manageFolder = null;
    let sharedFolder = null;

    if (accountFolder) {
        pagesFolder = ensureChildFolder(accountFolder, "Pages");
        manageFolder = ensureChildFolder(pagesFolder, "Manage");
        sharedFolder = ensureChildFolder(accountFolder, "Shared");

        function syncPage(def, folder) {
            let comp = managed.find(function (c) { return c.getMetadata(META_KEY) === def.id; });
            if (!comp) {
                comp = folder.addChild("Component", def.name);
                createdIds.push(comp.id);
                comp.setMetadata(NEWLY_CREATED_META_KEY, "true");
            }
            const st = comp.ensureStereotype(PAGE_STEREOTYPE);
            st.setProperty("Route", def.route);
            st.setProperty("Title", def.title);
            comp.setMetadata(META_KEY, def.id);
        }

        function syncShared(def, folder) {
            let comp = managed.find(function (c) { return c.getMetadata(META_KEY) === def.id; });
            if (!comp) {
                comp = folder.addChild("Component", def.name);
                createdIds.push(comp.id);
                comp.setMetadata(NEWLY_CREATED_META_KEY, "true");
            }
            comp.setMetadata(META_KEY, def.id);
        }

        definition.pages.forEach(function (p) { syncPage(p, pagesFolder); });
        definition.managePages.forEach(function (p) { syncPage(p, manageFolder); });
        sharedTargets.forEach(function (s) { syncShared(s, sharedFolder); });
    }

    element.setMetadata("authentication", securityType);

    if (accountFolder) {
        try {
            syncNavigations(getNavigationDefinitions(securityType));

            if (createdIds.length > 0) {
                const diagramElement = accountFolder.getChildren("Diagram").find(function (d) { return d.getName() === "Account"; });
                if (diagramElement) {
                    const diagram = await diagramElement.openDiagram();
                    const position = diagram.mousePosition || { x: 0, y: 0 };
                    diagram.layoutVisuals(createdIds, position, true);
                }
            }

            if (manageFolder.getChildren().length === 0) {
                manageFolder.delete();
            }
            if (pagesFolder.getChildren().length === 0) {
                pagesFolder.delete();
            }
            if (sharedFolder.getChildren().length === 0) {
                sharedFolder.delete();
            }
            const remaining = accountFolder.getChildren().filter(function (c) {
                return c !== pagesFolder && c !== sharedFolder && c.getSpecialization() !== "Diagram";
            });
            if (remaining.length === 0 && !pagesFolder.getParent() && !sharedFolder.getParent()) {
                accountFolder.getChildren("Diagram").forEach(function (d) { d.delete(); });
                accountFolder.delete();
            }
        } catch (e) {
            console.log("Navigation sync, diagram placement, or folder cleanup failed (non-fatal): " + e);
        }
    }
}

const stereotype = element.getStereotype(STEREOTYPE_ID);
const securityType = stereotype.getProperty("Authentication").getValue();
const definition = PAGE_DEFINITIONS[securityType];
const mudBlazorInstalled = application.isModuleInstalled("Intent.Blazor.Components.MudBlazor");
const sharedTargets = definition.shared.filter(function (s) {
    return !(HIDE_IF_MUDBLAZOR_IDS.indexOf(s.id) !== -1 && mudBlazorInstalled);
});
const allTargets = definition.pages.concat(definition.managePages, sharedTargets);
const targetIds = {};
allTargets.forEach(function (t) { targetIds[t.id] = true; });
const managedNow = findElements({ specialization: "Component" }).filter(function (c) { return c.hasMetadata(META_KEY); });
const toRemoveNow = managedNow.filter(function (c) { return !targetIds[c.getMetadata(META_KEY)]; });
const toAddCount = allTargets.filter(function (t) {
    return !managedNow.some(function (c) { return c.getMetadata(META_KEY) === t.id; });
}).length;

try {
    await dialogService.confirm(
    `Switching Security Type to "${securityType}" will modify the modelled Account pages/components by adding ${toAddCount} and removing ${toRemoveNow.length}. Continue?`
    );
    await runSync(securityType);
} catch {
    stereotype.getProperty("Authentication").setValue(element.getMetadata("authentication"));
}
